local ICON_B64 = ""

local function decodeB64(data)
  local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  local lookup = {}
  for i = 1, #chars do lookup[chars:sub(i, i)] = i - 1 end
  local out, buffer, bits = {}, 0, 0
  for i = 1, #data do
    local c = data:sub(i, i)
    if c ~= "=" then
      local value = lookup[c]
      if value then
        buffer = buffer * 64 + value
        bits = bits + 6
        if bits >= 8 then
          bits = bits - 8
          out[#out + 1] = string.char(math.floor(buffer / 2 ^ bits) % 256)
          buffer = buffer % 2 ^ bits
        end
      end
    end
  end
  return table.concat(out)
end

local ICON_PATH = "meci_hub_icon.png"
local MECI_ICON = "rbxassetid://136890595976124"
pcall(function()
  if type(writefile) ~= "function" or type(getcustomasset) ~= "function" then return end
  local bytes = type(base64) == "table" and type(base64.decode) == "function" and base64.decode(ICON_B64) or decodeB64(ICON_B64)
  writefile(ICON_PATH, bytes)
  local asset = getcustomasset(ICON_PATH)
  if type(asset) == "number" then
    MECI_ICON = "rbxassetid://" .. asset
  elseif type(asset) == "string" and asset ~= "" then
    MECI_ICON = asset
  end
end)

