local function callRemote(remote, ...)
  local args = {...}
  local ok, err
  if remote:IsA("RemoteFunction") then
    local done, result = false, nil
    local thread = task.spawn(function()
      ok, result = pcall(function() return remote:InvokeServer(table.unpack(args)) end)
      done = true
    end)
    local started = os.clock()
    repeat task.wait() until done or os.clock() - started > 4
    if not done then
      pcall(task.cancel, thread)
      return false, "timeout"
    end
    return ok, result
  end
  ok, err = pcall(function() remote:FireServer(table.unpack(args)) end)
  return ok, err
end

local function findRemote(patterns)
  local folders = {
    ReplicatedStorage:FindFirstChild("Network"),
    ReplicatedStorage:FindFirstChild("Packages"),
    ReplicatedStorage:FindFirstChild("Remotes"),
  }
  local function matches(inst)
    local name = string.lower(inst.Name)
    for _, pattern in ipairs(patterns) do
      if string.find(name, pattern, 1, true) then return true end
    end
    return false
  end
  for _, folder in ipairs(folders) do
    if folder then
      for _, inst in ipairs(folder:GetDescendants()) do
        if (inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") or inst:IsA("UnreliableRemoteEvent")) and matches(inst) then
          return inst
        end
      end
    end
  end
  for _, inst in ipairs(ReplicatedStorage:GetDescendants()) do
    if (inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") or inst:IsA("UnreliableRemoteEvent")) and matches(inst) then
      return inst
    end
  end
  return nil
end

local function callPatterns(patterns, ...)
  local key = table.concat(patterns, "|")
  local remote = RemoteCache[key]
  if not remote or not remote.Parent then
    remote = findRemote(patterns)
    RemoteCache[key] = remote
  end
  if not remote then return false, "missing remote" end
  return callRemote(remote, ...)
end

local function listRemotes()
  local names = {}
  local seen = {}
  for _, inst in ipairs(ReplicatedStorage:GetDescendants()) do
    if inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") or inst:IsA("UnreliableRemoteEvent") then
      local name = inst:GetFullName()
      if not seen[name] then
        seen[name] = true
        names[#names + 1] = name
      end
    end
  end
  return names
end

local function isTarget(inst, words)
  local name = string.upper(inst.Name)
  for _, word in ipairs(words) do
    if string.find(name, word, 1, true) then return true end
  end
  return false
end

local function findTargets(words)
  local list, seen = {}, {}
  for _, inst in ipairs(workspace:GetDescendants()) do
    if (inst:IsA("BasePart") or inst:IsA("Model")) and isTarget(inst, words) then
      local model = inst:IsA("Model") and inst or inst:FindFirstAncestorOfClass("Model") or inst
      if not seen[model] then
        seen[model] = true
        list[#list + 1] = model
      end
    end
  end
  return list
end

local function partOf(inst)
  if inst:IsA("BasePart") then return inst end
  return inst:FindFirstChildWhichIsA("BasePart", true)
end

local function positionOf(inst)
  local part = inst and partOf(inst) or nil
  return part and part.Position or nil
end

local function firePrompt(prompt)
  if type(fireproximityprompt) == "function" then
    return pcall(fireproximityprompt, prompt)
  end
  return false, "fireproximityprompt unavailable"
end

local function applyInstantInteract()
  for _, prompt in ipairs(workspace:GetDescendants()) do
    if prompt:IsA("ProximityPrompt") then
      pcall(function()
        prompt.HoldDuration = 0
        prompt.RequiresLineOfSight = false
        prompt.MaxActivationDistance = math.max(prompt.MaxActivationDistance, 20)
      end)
    end
  end
end

local function nearestTarget(words)
  local char = Player.Character
  local root = char and char:FindFirstChild("HumanoidRootPart")
  if not root then return nil, math.huge end
  local best, distance = nil, math.huge
  for _, target in ipairs(findTargets(words)) do
    local part = partOf(target)
    if part then
      local d = (part.Position - root.Position).Magnitude
      if d < distance then best, distance = target, d end
    end
  end
  return best, distance
end

local function virtualClick(point, quick)
  local cam = workspace.CurrentCamera
  if not cam then return false end
  point = point or Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
  local hold = quick and 0.002 or 0.02
  if UserInputService.TouchEnabled and not UserInputService.MouseEnabled then
    return pcall(function()
      VirtualInputManager:SendTouchEvent(1, 0, point.X, point.Y)
      task.wait(hold)
      VirtualInputManager:SendTouchEvent(1, 2, point.X, point.Y)
    end)
  end
  return pcall(function()
    VirtualInputManager:SendMouseButtonEvent(point.X, point.Y, 0, true, game, 1)
    task.wait(hold)
    VirtualInputManager:SendMouseButtonEvent(point.X, point.Y, 0, false, game, 1)
  end)
end

local function shootOnce()
  local target = nearestTarget({"BOX", "CRATE", "PACKAGE", "CARTON"})
  local cam = workspace.CurrentCamera
  if target and cam then
    local part = partOf(target)
    local screen, visible = cam:WorldToScreenPoint(part.Position)
    if visible then
      virtualClick(Vector2.new(screen.X, screen.Y))
      return target.Name
    end
  end
  virtualClick()
  return "screen center"
end

local function nearestPrompt(words)
  local char = Player.Character
  local root = char and char:FindFirstChild("HumanoidRootPart")
  if not root then return nil, math.huge end
  words = words or {"EGG", "NEST", "CARRY"}
  local best, distance = nil, math.huge
  for _, prompt in ipairs(workspace:GetDescendants()) do
    if prompt:IsA("ProximityPrompt") and prompt.Enabled then
      local ancestor = prompt:FindFirstAncestorWhichIsA("BasePart") or prompt.Parent
      local name = string.upper((ancestor and ancestor.Name or prompt.Name))
      local matched = false
      for _, word in ipairs(words) do
        if string.find(name, word, 1, true) then matched = true break end
      end
      local pos = positionOf(ancestor)
      if matched and pos then
        local d = (pos - root.Position).Magnitude
        if d < distance then best, distance = prompt, d end
      end
    end
  end
  return best, distance
end

local function stealOnce()
  local prompt = nearestPrompt({"EGG", "NEST", "CARRY"})
  if not prompt then return false, "no prompt" end
  local ancestor = prompt:FindFirstAncestorWhichIsA("BasePart") or prompt.Parent
  local char = Player.Character
  local root = char and char:FindFirstChild("HumanoidRootPart")
  local pos = positionOf(ancestor)
  if root and pos then
    root.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))
  end
  task.wait(0.15)
  local ok, note = firePrompt(prompt)
  return ok, ok and "prompt fired" or tostring(note)
end

local function trainOnce()
