local function uidOf(inst)
  for _, key in ipairs({"Uid", "UID", "Id", "ID", "AnimalUid", "PetUid", "EggUid"}) do
    local value = inst:GetAttribute(key)
    if value ~= nil then return value end
  end
  return nil
end

local function inventoryUid()
  for _, holder in ipairs({Player:FindFirstChild("Backpack"), Player.Character}) do
    if holder then
      for _, tool in ipairs(holder:GetChildren()) do
        local uid = uidOf(tool)
        if uid then return uid end
      end
    end
