end

local function placeHatchOnce()
  local uid = inventoryUid()
  if not uid then return false, "no egg uid" end
  local okPlace = callPatterns({"requestplaceegg", "placeegg", "place"}, uid)
  if not okPlace then return false, "place remote missing" end
  task.wait(0.4)
  local okHatch = callPatterns({"requesthatchegg", "hatchegg", "hatch"}, uid)
  if not okHatch then return false, "hatch remote missing" end
  task.wait(1)
  callPatterns({"requestcompletehatchegg", "completehatch", "complete"}, uid)
  callPatterns({"requestequip", "equip"}, uid)
  return true, "egg queued"
end

local function upgradeOnce()
  local results = {}
  local jobs = {
    {"upgrade gun", {"upgradegun", "gunupgrade", "upgradeshoot"}},
    {"upgrade speed", {"upgradespeed", "speedupgrade", "treadmill"}},
    {"upgrade base", {"upgradebase", "baseupgrade"}},
    {"claim", {"claim", "claimreward", "freegift"}},
  }
  for _, job in ipairs(jobs) do
    local ok = callPatterns(job[2])
    results[#results + 1] = job[1] .. "=" .. (ok and "ok" or "missing")
  end
  return table.concat(results, " ")
end

local function targetInfo(inst)
  local animal, rate
  local function add(key, value)
    if type(value) ~= "string" and type(value) ~= "number" then return end
    local text = tostring(value)
    local lower = string.lower(key)
    if not animal and (string.find(lower, "animal") or string.find(lower, "pet") or string.find(lower, "name") or string.find(lower, "type")) then
      animal = text
    end
    if not rate and (string.find(lower, "money") or string.find(lower, "cash") or string.find(lower, "rate") or string.find(lower, "value") or string.find(lower, "earn") or string.find(lower, "income")) then
      rate = text
    end
  end
  local scope = inst:IsA("Model") and inst or inst.Parent
  if scope then
    for key, value in pairs(scope:GetAttributes()) do add(key, value) end
    for _, child in ipairs(scope:GetDescendants()) do
      if child:IsA("StringValue") or child:IsA("NumberValue") or child:IsA("IntValue") then
        add(child.Name, child.Value)
      end
    end
  end
  return animal or inst.Name, rate or "?"
end

local function belongsTo(inst, root)
  while inst do
    if inst == root then return true end
    inst = inst.Parent
  end
  return false
end

local plotCache = nil
local function myPlot()
  if plotCache and plotCache.Parent then return plotCache end
  for _, inst in ipairs(workspace:GetDescendants()) do
    if inst:IsA("Model") or inst:IsA("BasePart") then
      local owner = inst:GetAttribute("Owner") or inst:GetAttribute("OwnerId") or inst:GetAttribute("OwnerName") or inst:GetAttribute("UserId") or inst:GetAttribute("Player")
      local name = string.upper(inst.Name)
      local owned = tostring(owner) == tostring(Player.UserId) or tostring(owner) == Player.Name or name == string.upper(Player.Name) or name == tostring(Player.UserId)
      if owned and positionOf(inst) then
        plotCache = inst
        return inst
      end
    end
  end
  return nil
end

local function carriedAnimal()
  local root = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
  if not root then return nil end
  local best, distance = nil, 15
  for _, inst in ipairs(findTargets({"ANIMAL", "PET", "CARRY", "PICKED", "BOUGHT"})) do
    if not belongsTo(inst, Player.Character) then
      local pos = positionOf(inst)
      if pos then
        local d = (pos - root.Position).Magnitude
        if d < distance then best, distance = inst, d end
      end
    end
  end
  return best
end

local function deliverTick(dt)
  if not Config.AutoDeliver then return false end
  local animal = carriedAnimal()
  local plot = myPlot()
  if not animal or not plot then return false end
  local part = partOf(animal)
  local root = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
  local plotPos = positionOf(plot)
  if not part or not root or not plotPos then return false end
  local speed = root.AssemblyLinearVelocity.Magnitude
  if speed < 1 then speed = 16 end
  local destination = Vector3.new(plotPos.X, plotPos.Y + Config.DeliverHeight, plotPos.Z)
  local current = part.Position
  local distance = (destination - current).Magnitude
  if distance < 0.2 then
    pcall(function() part.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
    return true
  end
  local step = math.min(distance, speed * dt)
  local nextPosition = current:Lerp(destination, step / distance)
  pcall(function()
    part.Anchored = false
    part.CFrame = CFrame.new(nextPosition)
    part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
  end)
  return true
end

local function rateNumber(rate)
  local value = tonumber(tostring(rate):match("[%d%.]+"))
  return value or 0
end

local function ownedAnimals()
  local plot = myPlot()
  if not plot then return {} end
  local list = {}
  for _, inst in ipairs(findTargets({"ANIMAL", "PET"})) do
    if belongsTo(inst, plot) then
      local _, rate = targetInfo(inst)
      list[#list + 1] = {Inst = inst, Uid = uidOf(inst), Rate = rateNumber(rate)}
    end
  end
  return list
end

local function equipBestOnce()
  local animals = ownedAnimals()
  if #animals == 0 then return false, "no animal in plot" end
  table.sort(animals, function(a, b) return a.Rate > b.Rate end)
  local best = animals[1]
  local ok = false
  if best.Uid then ok = callPatterns({"requestequip", "equipanimal", "equip"}, best.Uid) end
  if not ok then ok = callPatterns({"requestequip", "equipanimal", "equip"}, best.Inst) end
  return ok, ok and (best.Inst.Name .. " $" .. best.Rate .. "/s") or "equip remote missing"
end

local function inventorySignature()
  local bag = Player:FindFirstChild("Backpack")
  local bagCount = bag and #bag:GetChildren() or 0
  return tostring(bagCount) .. ":" .. tostring(#ownedAnimals())
end

local function clearEsp()
  for _, gui in pairs(espObjects) do
    pcall(function() gui:Destroy() end)
  end
  espObjects = {}
end

local function refreshEsp()
  if not Config.EspBox and not Config.EspEgg then
    clearEsp()
    return
  end
  local host = type(gethui) == "function" and gethui() or CoreGui
  local char = Player.Character
  local root = char and char:FindFirstChild("HumanoidRootPart")
  local groups = {}
  if Config.EspBox then groups[#groups + 1] = {"BOX", "CRATE", "PACKAGE", "CARTON"} end
  if Config.EspEgg then groups[#groups + 1] = {"EGG", "NEST"} end
  local active = {}
  for _, words in ipairs(groups) do
    for _, target in ipairs(findTargets(words)) do
      local part = partOf(target)
      if part and (not root or (part.Position - root.Position).Magnitude <= Config.EspRange) then
        active[target] = true
        local gui = espObjects[target]
        if not gui or not gui.Parent then
          gui = Instance.new("BillboardGui")
          gui.Name = "MeciHubEsp"
          gui.Adornee = part
          gui.AlwaysOnTop = true
          gui.Size = UDim2.new(0, 240, 0, 46)
          gui.StudsOffset = Vector3.new(0, 2.5, 0)
          gui.MaxDistance = Config.EspRange
          local label = Instance.new("TextLabel")
          label.Name = "Label"
          label.Size = UDim2.new(1, 0, 1, 0)
          label.BackgroundColor3 = Color3.fromRGB(10, 10, 15)
          label.BackgroundTransparency = 0.35
          label.TextColor3 = Color3.new(1, 1, 1)
          label.TextSize = 14
          label.Font = Enum.Font.GothamBold
          label.Parent = gui
          gui.Parent = host
          espObjects[target] = gui
        end
        local animal, rate = targetInfo(target)
        local label = gui:FindFirstChild("Label")
        if label then label.Text = animal .. "  |  $" .. rate .. "/s" end
      end
    end
  end
  for target, gui in pairs(espObjects) do
    if not active[target] then
      pcall(function() gui:Destroy() end)
      espObjects[target] = nil
    end
  end
end

task.spawn(function()
  local lastShoot, lastSteal, lastPlace, lastUpgrade, lastTrain, lastEquip = 0, 0, 0, 0, 0, 0
  while true do
    task.wait(0.1)
    local now = os.clock()
    local ok, err = pcall(function()
      if Config.AutoShoot and now - lastShoot >= Config.ShootDelay then
        lastShoot = now
        local hit = shootOnce()
        action("Shoot " .. hit)
      end
      if Config.AutoSteal and now - lastSteal >= Config.StealDelay then
        lastSteal = now
        local done, note = stealOnce()
        action("Steal " .. (done and note or note))
      end
      if Config.AutoPlaceHatch and now - lastPlace >= Config.PlaceDelay then
        lastPlace = now
        local done, note = placeHatchOnce()
        action("Place/Hatch " .. (done and note or note))
      end
      if Config.AutoUpgrade and now - lastUpgrade >= Config.UpgradeDelay then
        lastUpgrade = now
        action("Upgrade " .. upgradeOnce())
      end
      if Config.AutoTrain and now - lastTrain >= Config.TrainDelay then
        lastTrain = now
        local done, note = trainOnce()
        action("Train " .. (done and note or note))
      end
      if Config.AutoEquipBest and now - lastEquip >= 1 then
        lastEquip = now
        local signature = inventorySignature()
        if signature ~= lastInventorySignature then
          lastInventorySignature = signature
          local done, note = equipBestOnce()
          action("Equip best " .. (done and note or note))
        end
      end
    end)
    if not ok then warn("[Meci Hub] Farm tick error: " .. tostring(err)) end
  end
end)

task.spawn(function()
  local lastKill = 0
  while true do
    task.wait(0.05)
    if Config.KillAura and os.clock() - lastKill >= Config.KillAuraDelay then
      lastKill = os.clock()
      pcall(function()
        local done, note = killAuraOnce()
        if done then action("Kill aura " .. note) end
      end)
    end
  end
end)

task.spawn(function()
  while true do
    task.wait(1)
    if Config.InstantInteract then pcall(applyInstantInteract) end
  end
end)

RunService.Heartbeat:Connect(function(dt)
  pcall(deliverTick, dt)
end)

task.spawn(function()
  while true do
    task.wait(0.25)
    if Config.EspAutoRefresh and (Config.EspBox or Config.EspEgg) then
      pcall(refreshEsp)
    elseif not Config.EspBox and not Config.EspEgg and next(espObjects) then
      clearEsp()
    end
  end
end)

